/* Optional: cursor-following glow on the focus-area cards */
(function () {
  document.querySelectorAll('.sd-card').forEach(function (card) {
    card.addEventListener('pointermove', function (e) {
      var r = card.getBoundingClientRect();
      card.style.setProperty('--mx', (e.clientX - r.left) + 'px');
      card.style.setProperty('--my', (e.clientY - r.top) + 'px');
    });
  });
})();

/* Easter egg: a working terminal in the hero.
   Type a topic (science, engineering, mathematics, technology, space, nature),
   press Enter, watch it "execute", then it redirects to that topic. */
(function () {
  var term = document.getElementById('sd-term');
  var input = document.getElementById('sd-term-input');
  var out = document.getElementById('sd-term-out');
  if (!term || !input || !out) return;

  var TOPICS = {
    science: '/category/stem/science/',
    engineering: '/category/stem/engineering/',
    mathematics: '/category/stem/mathematics/',
    technology: '/category/stem/technology/',
    space: '/category/stem/space/',
    nature: '/category/stem/nature/'
  };
  var ALIASES = { sci: 'science', eng: 'engineering', math: 'mathematics', maths: 'mathematics', tech: 'technology' };
  var fast = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var busy = false;

  function print(text, cls) {
    var d = document.createElement('div');
    if (cls) d.className = cls;
    d.textContent = text; /* textContent keeps typed text inert */
    out.appendChild(d);
    out.scrollTop = out.scrollHeight;
    return d;
  }
  function wait(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, fast ? 0 : ms); });
  }

  async function launch(topic) {
    busy = true;
    var url = TOPICS[topic];
    print('> resolving department "stem" ...');
    await wait(450);
    print('> locating module: ' + topic + ' ... ok', 'ok');
    await wait(450);
    var bar = print('> compiling articles  [..........]   0%');
    for (var i = 1; i <= 10; i++) {
      await wait(90);
      bar.textContent = '> compiling articles  [' + '#'.repeat(i) + '.'.repeat(10 - i) + ']  ' + (i * 10) + '%';
    }
    await wait(250);
    print('> executing: explore --department stem --topic ' + topic, 'ok');
    await wait(500);
    print('> redirecting to ' + url + ' ...', 'ok');
    await wait(600);
    window.location.href = url;
  }

  function run(raw) {
    var cmd = raw.trim().toLowerCase();
    if (!cmd) return;
    print('$ ' + raw.trim());
    if (cmd === 'clear' || cmd === 'cls') { out.textContent = ''; return; }
    if (cmd === 'help' || cmd === 'ls' || cmd === '?') {
      print('modules: ' + Object.keys(TOPICS).join(' | '), 'ok');
      print('type one and press enter. (psst: try "whoami")');
      return;
    }
    if (cmd === 'whoami') { print('a curious human. welcome to the stem department.', 'ok'); return; }
    if (cmd.indexOf('sudo') === 0) { print('nice try. no root needed, everything here is open to explore.', 'ok'); return; }
    /* accepts "science", "sci", "--topic science", or "explore --department stem science" */
    var word = cmd.split(/\s+/).pop().replace(/^-+/, '');
    var topic = ALIASES[word] || word;
    if (Object.prototype.hasOwnProperty.call(TOPICS, topic)) { launch(topic); return; }
    print('error: unknown topic "' + word + '"', 'err');
    print('try: ' + Object.keys(TOPICS).join(' | '));
  }

  input.addEventListener('keydown', function (e) {
    if (e.key !== 'Enter' || busy) return;
    e.preventDefault();
    var value = input.value;
    input.value = '';
    run(value);
  });
  term.addEventListener('click', function () { input.focus(); });

  /* if the visitor comes back with the Back button, reset the terminal */
  window.addEventListener('pageshow', function (e) {
    if (e.persisted) { busy = false; out.textContent = ''; input.value = ''; }
  });
})();

/* Quantum background: a fixed, full-screen field behind the whole page.
   Superposition clouds, entangled pairs and wave packets. Move the pointer near a
   particle to "measure" it: it collapses to a sharp dot and its entangled partner
   collapses with it. */
(function () {
  var canvas = document.getElementById('sd-quantum');
  if (!canvas || !canvas.getContext) return;
  var ctx = canvas.getContext('2d');
  if (!ctx) return;

  /* a fixed canvas must not sit inside a transformed or clipped ancestor, so park it
     directly on <body> (and drop any stale copy, e.g. after an Elementor editor refresh) */
  var stale = document.querySelectorAll('canvas.sd-quantum');
  for (var s = 0; s < stale.length; s++) { if (stale[s] !== canvas) stale[s].parentNode.removeChild(stale[s]); }
  if (canvas.parentNode !== document.body) document.body.appendChild(canvas);

  var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var dpr = 1;
  var COLORS = ['0,229,255', '122,167,255', '201,184,255'];
  var W = 0, H = 0, parts = [], mouse = { x: -9999, y: -9999 };
  var running = false, last = 0, t = reduce ? 3000 : 0, raf = 0;

  function dist2(a, b) { var dx = a.x - b.x, dy = a.y - b.y; return dx * dx + dy * dy; }

  function init() {
    var n = Math.max(28, Math.min(90, Math.round(W * H / 16000)));
    var i, j, d, best, bd;
    parts = [];
    for (i = 0; i < n; i++) {
      parts.push({
        x: Math.random() * W, y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.18, vy: (Math.random() - 0.5) * 0.18,
        r: 14 + Math.random() * 26,   /* cloud radius = positional uncertainty */
        ph: Math.random() * 6.283,
        col: COLORS[i % 3],
        c: 0,                         /* collapse amount: 0 = cloud, 1 = measured */
        mate: -1                      /* entangled partner */
      });
    }
    for (i = 0; i < n; i++) {
      if (parts[i].mate !== -1) continue;
      best = -1; bd = Infinity;
      for (j = i + 1; j < n; j++) {
        if (parts[j].mate !== -1) continue;
        d = dist2(parts[i], parts[j]);
        if (d < bd) { bd = d; best = j; }
      }
      if (best !== -1) { parts[i].mate = best; parts[best].mate = i; }
    }
  }

  function resize() {
    var w = canvas.clientWidth, h = canvas.clientHeight, i;
    if (!w || !h || (w === W && h === H)) return;
    var ow = W, oh = H;
    W = w; H = h;
    /* a full-screen layer redraws every frame: cap the pixel count so big or retina screens stay smooth */
    dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2, Math.sqrt(3000000 / (W * H))));
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (!parts.length) { init(); }
    else if (ow && oh) { for (i = 0; i < parts.length; i++) { parts[i].x *= W / ow; parts[i].y *= H / oh; } }
    if (reduce) draw();
  }

  function step(dt) {
    var k = dt / 16.7, i, p, d, m = [];
    for (i = 0; i < parts.length; i++) {
      p = parts[i];
      p.vx += (Math.random() - 0.5) * 0.01 * k;
      p.vy += (Math.random() - 0.5) * 0.01 * k;
      p.vx = Math.max(-0.25, Math.min(0.25, p.vx));
      p.vy = Math.max(-0.25, Math.min(0.25, p.vy));
      p.x += p.vx * k; p.y += p.vy * k;
      if (p.x < -40) p.x = W + 40; else if (p.x > W + 40) p.x = -40;
      if (p.y < -40) p.y = H + 40; else if (p.y > H + 40) p.y = -40;
      d = Math.sqrt(dist2(p, mouse));
      m[i] = Math.max(0, Math.min(1, 1 - d / 130));   /* how strongly the pointer "observes" it */
    }
    for (i = 0; i < parts.length; i++) {
      p = parts[i];
      var target = Math.max(m[i], p.mate >= 0 ? m[p.mate] * 0.85 : 0);  /* partner collapses too */
      p.c += (target - p.c) * Math.min(1, dt * 0.006);
    }
  }

  function wavePacket(y, amp, kk, speed, sigma, off, dir, col) {
    var span = W + 4 * sigma;
    var cx = -2 * sigma + ((((t * speed + off) % 1) + 1) % 1) * span;
    var x, env, started = false;
    ctx.beginPath();
    for (x = 0; x <= W; x += 4) {
      env = Math.exp(-((x - cx) * (x - cx)) / (2 * sigma * sigma));
      if (env < 0.02) continue;
      var yy = y + env * amp * Math.sin(kk * x - dir * t * 0.004);
      if (!started) { ctx.moveTo(x, yy); started = true; } else { ctx.lineTo(x, yy); }
    }
    ctx.strokeStyle = 'rgba(' + col + ',0.4)';
    ctx.lineWidth = 1.2;
    ctx.stroke();
  }

  function draw() {
    var i, p, q, g, a, spread, k, ang, rr, d, fade, along;
    ctx.clearRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'lighter';

    /* two wave packets drifting across the screen in opposite directions */
    wavePacket(H * 0.24, 14, 0.06, 0.00004, W * 0.13, 0, 1, '0,229,255');
    wavePacket(H * 0.74, 14, 0.045, -0.00003, W * 0.13, 0.37, -1, '201,184,255');

    /* entanglement links */
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 6]);
    ctx.lineDashOffset = -t * 0.02;
    for (i = 0; i < parts.length; i++) {
      p = parts[i];
      if (p.mate < i) continue;
      q = parts[p.mate];
      d = Math.sqrt(dist2(p, q));
      fade = Math.max(0.04, 1 - d / (0.6 * Math.max(W, H)));
      a = (0.1 + 0.3 * Math.max(p.c, q.c)) * fade;
      ctx.strokeStyle = 'rgba(122,167,255,' + a + ')';
      ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(q.x, q.y); ctx.stroke();
    }
    ctx.setLineDash([]);
    for (i = 0; i < parts.length; i++) {          /* a tiny photon travelling each link */
      p = parts[i];
      if (p.mate < i) continue;
      q = parts[p.mate];
      along = ((t * 0.0004 + i * 0.137) % 1);
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.beginPath();
      ctx.arc(p.x + (q.x - p.x) * along, p.y + (q.y - p.y) * along, 1.3, 0, 6.283);
      ctx.fill();
    }

    /* particles: probability clouds that collapse when observed */
    for (i = 0; i < parts.length; i++) {
      p = parts[i];
      spread = p.r * (1 - 0.85 * p.c) * (0.85 + 0.15 * Math.sin(t * 0.0015 + p.ph));
      g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, spread);
      g.addColorStop(0, 'rgba(' + p.col + ',' + (0.3 + 0.5 * p.c) + ')');
      g.addColorStop(1, 'rgba(' + p.col + ',0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(p.x, p.y, spread, 0, 6.283); ctx.fill();

      for (k = 1; k <= 3; k++) {                  /* superposition "ghost" positions */
        ang = t * 0.001 * k + p.ph * k;
        rr = spread * 0.9 * (0.5 + 0.5 * Math.sin(t * 0.0007 * k + p.ph));
        ctx.fillStyle = 'rgba(' + p.col + ',' + (0.5 * (1 - p.c)) + ')';
        ctx.beginPath();
        ctx.arc(p.x + Math.cos(ang) * rr, p.y + Math.sin(ang) * rr, 1.5, 0, 6.283);
        ctx.fill();
      }

      ctx.fillStyle = 'rgba(255,255,255,' + (0.45 + 0.5 * p.c) + ')';
      ctx.beginPath(); ctx.arc(p.x, p.y, 1.6 + 2.4 * p.c, 0, 6.283); ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
  }

  function stop() {
    running = false;
    if (raf) { cancelAnimationFrame(raf); raf = 0; }
  }
  function frame(now) {
    raf = 0;
    if (!running) return;
    if (!canvas.isConnected) { stop(); return; }   /* the page replaced us (editor refresh): quit quietly */
    var dt = Math.max(0, Math.min(48, now - (last || now)));   /* never negative, never a huge jump */
    last = now; t += dt;
    step(dt); draw();
    raf = requestAnimationFrame(frame);
  }
  function start() {
    if (reduce || running || document.hidden) return;
    running = true; last = 0;
    raf = requestAnimationFrame(frame);
  }

  /* the pointer "observes" the particles under it, anywhere on the screen */
  function unobserve() { mouse.x = -9999; mouse.y = -9999; }
  window.addEventListener('pointermove', function (e) { mouse.x = e.clientX; mouse.y = e.clientY; }, { passive: true });
  document.documentElement.addEventListener('pointerleave', unobserve);
  window.addEventListener('blur', unobserve);
  window.addEventListener('pointercancel', unobserve);
  window.addEventListener('pointerup', function (e) { if (e.pointerType && e.pointerType !== 'mouse') unobserve(); });

  document.addEventListener('visibilitychange', function () { if (document.hidden) stop(); else start(); });
  if ('ResizeObserver' in window) { new ResizeObserver(resize).observe(canvas); }
  else { window.addEventListener('resize', resize); }

  resize();
  start();
})();

( () => {
	const lazyloadRunObserver = () => {
		const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
		const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
			entries.forEach( ( entry ) => {
				if ( entry.isIntersecting ) {
					let lazyloadBackground = entry.target;
					if( lazyloadBackground ) {
						lazyloadBackground.classList.add( 'e-lazyloaded' );
					}
					lazyloadBackgroundObserver.unobserve( entry.target );
				}
			});
		}, { rootMargin: '200px 0px 200px 0px' } );
		lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
			lazyloadBackgroundObserver.observe( lazyloadBackground );
		} );
	};
	const events = [
		'DOMContentLoaded',
		'elementor/lazyload/observe',
	];
	events.forEach( ( event ) => {
		document.addEventListener( event, lazyloadRunObserver );
	} );
} )();
